<script setup>
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { CalendarPlus, Search, Filter, Plus, X, Pencil, Eye, UserRound, CarFront, Check, Play, CircleCheck, Ban, MapPin, Route, Clock3 } from 'lucide-vue-next'
import { readData, currentSession, toLocalDateTimeString } from '../services/storage'
import { money, dateTime } from '../services/fareService'
import { createBooking, updateBooking, cancelBooking, assignResources, transitionBooking } from '../services/bookingService'
import { estimateFare } from '../services/fareService'
const user = currentSession(), tick = ref(0), search = ref(''), filter = ref('All'), showForm = ref(false), editing = ref(null), selected = ref(null), error = ref(''), success = ref('')
const saving = ref(false)
const blank = () => ({ pickup: '', destination: '', scheduledAt: '', passengers: 1, estimatedKm: 5 })
const form = ref(blank()), data = computed(() => { tick.value; return readData() }), admin = computed(() => user.role === 'admin')
const rows = computed(() => data.value.bookings.filter(b => (admin.value || b.passengerId === user.id) && (filter.value === 'All' || b.status === filter.value) && [b.code, b.passengerName, b.pickup, b.destination].some(x => String(x || '').toLowerCase().includes(search.value.toLowerCase()))))
const drivers = computed(() => data.value.drivers.filter(d => d.status !== 'Inactive'))
const vehicles = computed(() => data.value.vehicles.filter(v => v.status !== 'Maintenance'))
const minDate = new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 16)
const refresh = () => tick.value++
onMounted(() => window.addEventListener('taxigo:data-updated', refresh))
onUnmounted(() => window.removeEventListener('taxigo:data-updated', refresh))
function openNew() { editing.value = null; form.value = blank(); error.value = ''; success.value = ''; showForm.value = true }
function openEdit(b) { editing.value = b.id; form.value = { pickup: b.pickup, destination: b.destination, scheduledAt: toLocalDateTimeString(b.scheduledAt), passengers: b.passengers, estimatedKm: b.estimatedKm }; error.value = ''; showForm.value = true }
function save() { error.value = ''; success.value = ''; if (saving.value) return; saving.value = true; try { if (editing.value) updateBooking(editing.value, form.value, user); else createBooking(form.value, user); showForm.value = false; success.value = editing.value ? 'Booking updated.' : 'Booking created successfully.'; form.value = blank() } catch (e) { error.value = e.message } finally { saving.value = false } }
function act(fn) { error.value = ''; success.value = ''; try { fn(); selected.value = null; success.value = 'Booking updated successfully.' } catch (e) { error.value = e.message } }
function assign(b) { const driverId = document.getElementById('driver-' + b.id)?.value, vehicleId = document.getElementById('vehicle-' + b.id)?.value; if (!driverId || !vehicleId) { error.value = 'Choose both a driver and a vehicle.'; return } act(() => assignResources(b.id, driverId, vehicleId)) }
function statusClass(s) { return s.toLowerCase().replaceAll(' ', '-') }
const farePreview = computed(() => {
  try { return money(estimateFare(data.value.settings, Number(form.value.estimatedKm) || 0)) } catch { return money(0) }
})
</script>
<template><div class="page-heading"><div><div class="eyebrow">{{admin?'OPERATIONS':'PASSENGER PORTAL'}}</div><h1>{{admin?'Booking management':'My bookings'}}</h1><p>{{admin?'Review requests, assign your fleet, and manage each ride.':'Request a ride and keep track of your upcoming trips.'}}</p></div><button class="btn btn-primary" @click="openNew"><Plus :size="17"/> {{admin?'New booking':'Book a ride'}}</button></div>
<div v-if="success" class="alert alert-success"><Check :size="17"/>{{success}}<button @click="success=''"><X :size="16"/></button></div><div v-if="error&&!showForm" class="alert alert-error"><X :size="17"/>{{error}}<button @click="error=''"><X :size="16"/></button></div>
<div class="list-toolbar"><div class="search-field"><Search :size="17"/><input v-model="search" placeholder="Search bookings, routes…"/></div><div class="filter-field"><Filter :size="16"/><select v-model="filter"><option>All</option><option>Pending</option><option>Confirmed</option><option>In Progress</option><option>Completed</option><option>Cancelled</option></select></div><span class="results-count">{{rows.length}} record{{rows.length===1?'':'s'}}</span></div>
<section class="panel data-panel"><div class="table-wrap"><table><thead><tr><th>BOOKING</th><th>ROUTE DETAILS</th><th>SCHEDULE</th><th>PASSENGER</th><th>FARE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="b in rows" :key="b.id"><td><strong class="booking-code">{{b.code}}</strong><small class="cell-sub">Created {{new Date(b.createdAt).toLocaleDateString()}}</small></td><td><div class="route-cell"><span><MapPin :size="12"/>{{b.pickup}}</span><span class="route-arrow">↓</span><span><MapPin :size="12"/>{{b.destination}}</span><small>{{b.estimatedKm}} estimated km · {{b.passengers}} passenger(s)</small></div></td><td>{{dateTime(b.scheduledAt)}}</td><td>{{b.passengerName}}</td><td><strong>{{money(b.fare)}}</strong></td><td><span class="status-pill" :class="statusClass(b.status)">{{b.status}}</span></td><td><div class="action-row"><button class="mini-action" title="View details" @click="selected=b"><Eye :size="16"/></button><button v-if="b.status==='Pending'||b.status==='Confirmed'" class="mini-action" title="Edit booking" @click="openEdit(b)"><Pencil :size="15"/></button><button v-if="!['Completed','Cancelled'].includes(b.status)" class="mini-action danger-action" title="Cancel booking" @click="act(()=>cancelBooking(b.id,user))"><Ban :size="15"/></button></div></td></tr><tr v-if="!rows.length"><td colspan="7"><div class="empty-state"><CalendarPlus :size="32"/><strong>No matching bookings</strong><p>Try a different filter or create a booking.</p><button class="btn btn-secondary" @click="openNew">Create booking</button></div></td></tr></tbody></table></div></section>
<section v-if="admin" class="panel assignment-panel"><div class="panel-heading"><div><h3>Assignment queue</h3><p>Assign an eligible driver and vehicle to pending or confirmed bookings.</p></div><span class="queue-count">{{data.bookings.filter(b=>['Pending','Confirmed'].includes(b.status)).length}} to review</span></div><div v-for="b in data.bookings.filter(x=>['Pending','Confirmed'].includes(x.status))" :key="b.id" class="assignment-row"><div class="assignment-trip"><strong>{{b.code}} · {{b.passengerName}}</strong><span>{{b.pickup}} → {{b.destination}}</span><small>{{b.passengers}} passenger(s) · {{money(b.fare)}}</small></div><div class="assignment-select"><label :for="'driver-'+b.id">Driver</label><select :id="'driver-'+b.id" :value="b.driverId||''"><option value="">Choose driver</option><option v-for="d in drivers" :key="d.id" :value="d.id" :disabled="data.bookings.some(o=>o.id!==b.id&&['Confirmed','In Progress'].includes(o.status)&&o.driverId===d.id)">{{d.name}}</option></select></div><div class="assignment-select"><label :for="'vehicle-'+b.id">Vehicle</label><select :id="'vehicle-'+b.id" :value="b.vehicleId||''"><option value="">Choose vehicle</option><option v-for="v in vehicles" :key="v.id" :value="v.id" :disabled="v.capacity<b.passengers||data.bookings.some(o=>o.id!==b.id&&['Confirmed','In Progress'].includes(o.status)&&o.vehicleId===v.id)">{{v.plate}} · {{v.model}} ({{v.capacity}} seats)</option></select></div><button class="btn btn-primary btn-small" @click="assign(b)"><Check :size="15"/> Assign</button></div><div v-if="!data.bookings.some(b=>['Pending','Confirmed'].includes(b.status))" class="empty-inline">All caught up — no bookings need assignment.</div></section>
<section v-if="admin" class="panel assignment-panel"><div class="panel-heading"><div><h3>Ride control</h3><p>Advance a confirmed ride through its lifecycle.</p></div></div><div v-for="b in data.bookings.filter(x=>['Confirmed','In Progress'].includes(x.status))" :key="b.id" class="ride-control-row"><div class="ride-control-icon"><CarFront :size="19"/></div><div class="assignment-trip"><strong>{{b.code}} · {{b.status}}</strong><span>{{b.pickup}} → {{b.destination}}</span><small>{{data.drivers.find(d=>d.id===b.driverId)?.name||'No driver'}} · {{data.vehicles.find(v=>v.id===b.vehicleId)?.plate||'No vehicle'}}</small></div><button v-if="b.status==='Confirmed'" class="btn btn-secondary btn-small" @click="act(()=>transitionBooking(b.id,'In Progress'))"><Play :size="15"/> Start ride</button><button v-else class="btn btn-primary btn-small" @click="act(()=>transitionBooking(b.id,'Completed'))"><CircleCheck :size="15"/> Complete ride</button></div><div v-if="!data.bookings.some(b=>['Confirmed','In Progress'].includes(b.status))" class="empty-inline">No active rides at the moment.</div></section>
<div v-if="showForm" class="modal-backdrop" @click.self="showForm=false"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">{{editing?'UPDATE DETAILS':'NEW RIDE REQUEST'}}</div><h2>{{editing?'Edit booking':'Book a taxi'}}</h2><p class="muted">Enter your trip details. Fare is an estimate, not a live quote.</p></div><button class="icon-button" @click="showForm=false"><X/></button></div><form class="form-stack" @submit.prevent="save"><div class="form-grid"><label>Pickup location<input v-model.trim="form.pickup" required maxlength="160" placeholder="e.g. Cebu IT Park"/></label><label>Destination<input v-model.trim="form.destination" required maxlength="160" placeholder="e.g. Ayala Center Cebu"/></label></div><div class="form-grid"><label>Date and time<input v-model="form.scheduledAt" type="datetime-local" :min="minDate" required/></label><label>Passengers<select v-model.number="form.passengers" required><option v-for="n in 7" :key="n" :value="n">{{n}} passenger{{n>1?'s':''}}</option></select></label></div><label>Estimated distance (km)<input v-model.number="form.estimatedKm" type="number" min="0.1" max="500" step="0.1" required/><small class="field-help">Enter a manually estimated distance between 0.1 and 500 km.</small></label><div class="fare-preview"><div><span>Estimated fare</span><small>Base + distance rate + service fee</small></div><strong>{{ farePreview }}</strong></div><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="showForm=false">Cancel</button><button type="submit" class="btn btn-primary" :disabled="saving">{{ saving ? 'Saving…' : (editing ? 'Save changes' : 'Submit booking') }}</button></div></form></section></div>
<div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">BOOKING DETAILS</div><h2>{{selected.code}}</h2><p class="muted">{{dateTime(selected.scheduledAt)}}</p></div><button class="icon-button" @click="selected=null"><X/></button></div><div class="detail-list"><div><span>Passenger</span><strong>{{selected.passengerName}}</strong></div><div><span>Pickup</span><strong>{{selected.pickup}}</strong></div><div><span>Destination</span><strong>{{selected.destination}}</strong></div><div><span>Estimated distance</span><strong>{{selected.estimatedKm}} km</strong></div><div><span>Passengers</span><strong>{{selected.passengers}}</strong></div><div><span>Driver</span><strong>{{data.drivers.find(d=>d.id===selected.driverId)?.name||'Not assigned'}}</strong></div><div><span>Vehicle</span><strong>{{data.vehicles.find(v=>v.id===selected.vehicleId)?.plate||'Not assigned'}}</strong></div><div><span>Estimated fare</span><strong>{{money(selected.fare)}}</strong></div><div><span>Status</span><span class="status-pill" :class="statusClass(selected.status)">{{selected.status}}</span></div></div><button class="btn btn-primary btn-full modal-done" @click="selected=null">Done</button></section></div>
</template>